#!/usr/bin/env Rscript
# Export final manuscript data only; existing legacy Supplementary Data remain.
suppressPackageStartupMessages(library(data.table))
ff<-grep('^--file=',commandArgs(FALSE),value=TRUE);rec<-dirname(normalizePath(sub('^--file=','',ff)));root<-dirname(rec);dst<-file.path(root,'supplementary_data');dir.create(dst,showWarnings=FALSE)
cx<-file.path(rec,'cross_dataset');ex<-file.path(rec,'candidate_validation');rp<-file.path(rec,'upr_rpe1_validation');ps<-file.path(cx,'phase2_upr_rpe1');li<-file.path(rec,'independent_lineage')
index<-list();ii<-0L
add<-function(from,folder,name=basename(from),description=''){
 stopifnot(file.exists(from));to<-file.path(dst,folder,name);dir.create(dirname(to),recursive=TRUE,showWarnings=FALSE);stopifnot(file.copy(from,to,overwrite=TRUE));d<-fread(to);ii<<-ii+1L;index[[ii]]<<-data.table(file=file.path(folder,name),rows=nrow(d),columns=ncol(d),description=description)
}
export<-function(d,folder,name,description){to<-file.path(dst,folder,name);dir.create(dirname(to),recursive=TRUE,showWarnings=FALSE);fwrite(d,to,sep='\t');ii<<-ii+1L;index[[ii]]<<-data.table(file=file.path(folder,name),rows=nrow(d),columns=ncol(d),description=description)}
for(f in c('final_gene_universe.tsv','final_axis_membership.tsv','final_module_gene_coverage.tsv','analysis_denominators.tsv'))add(file.path(cx,f),'measurement',description='Five-study common measurement definitions and dataset-specific accounting')
inv<-fread(file.path(cx,'final_source_inventory.tsv'));inv[,source_file:=basename(source_file)];inv[,modified:=NULL];setnames(inv,'source_file','source_object');export(inv,'measurement','final_source_inventory.tsv','Measured feature counts and duplicate-symbol accounting per source object; local locations are omitted')
for(f in c('phase2_gene_universe.tsv','phase2_UPR_members.tsv'))add(file.path(ps,f),'measurement',sub('^phase2_','RPE1_',f),'Targeted K562/RPE1 measurement definitions; earlier five-study universe remains separate')
redundant<-file.path(dst,'measurement/null100_module_membership.tsv');if(file.exists(redundant))unlink(redundant)
spec<-readRDS(file.path(ps,'phase2_axis_spec.rds'));mem<-rbindlist(lapply(names(spec),function(axis)rbindlist(lapply(c('positive','negative'),function(sign)data.table(axis=axis,sign=sign,gene=spec[[axis]][[sign]])))));export(mem,'measurement','RPE1_all105_axis_membership.tsv','Exact positive/negative memberships for UPR, all100 null modules, short modules and E2F')
for(f in c('primary_response_rmse_by_axis_group.tsv','direct_state_value_cluster_comparisons.tsv','partition_sensitivity.tsv','paired_partition_response_sensitivity.tsv','paired_partition_reliability_sensitivity.tsv','conditional_model_comparisons.tsv','response_metrics_by_axis.tsv'))add(file.path(cx,f),'study_transfer',description='Fixed study-held-out model errors or paired conditional cluster/partition sensitivities')
for(f in c('gene.tsv.gz','metric.tsv.gz','choice.tsv.gz','contrast.tsv.gz','null.tsv.gz','comparator_availability.tsv','gene_sensitivity.tsv.gz','metric_sensitivity.tsv.gz','choice_sensitivity.tsv.gz','contrast_sensitivity.tsv.gz','null_sensitivity.tsv.gz','secondary_integrated_ranking.tsv'))add(file.path(ex,f),'external_validation',paste0('candidate_',f),'Original fixed aggregate-priority test; primary or declared sensitivity as filename indicates')
for(f in c('harmonized_discovery_ranking.tsv','harmonized_adamson_candidates.tsv','harmonized_frangieh_candidates.tsv'))add(file.path(ex,f),'external_validation',sub('^harmonized_','source_frozen_',f),'Discovery-only candidate rankings fixed before external response evaluation')
for(f in c('exploratory_axis_conservation.tsv','exploratory_all_gene_axis_effects.tsv.gz','UPR_exact_composition_correlation_sensitivity.tsv','UPR_exact_numerator_denominator_moments.tsv','exploratory_UPR_direction_agreement.tsv','exploratory_axis_minimal_covariate_sensitivities.tsv','exploratory_paired_context_correlation_differences.tsv','exploratory_axis_leave_one_gene_out_summary.tsv','exploratory_equal_cell_axis_summary.tsv','exploratory_equal_cell_metadata_counts.tsv','exploratory_vector_prediction.tsv'))add(file.path(ex,f),'external_validation',description='Exploratory complete48-test family or explicitly named fixed-cohort robustness control')
for(f in c('all438_gene_UPR_response_and_fixed_rank.tsv','RPE1_gene_effects_all105.tsv.gz','primary_Holm3_endpoints.tsv','complete_case_baseline_utility.tsv','primary_all100_module_controls.tsv','primary_module_specificity_calibration.tsv','complete_covariate_sensitivity_endpoints.tsv','complete_covariate_all100_module_controls.tsv','complete_covariate_module_specificity_calibration.tsv','strict_RPE_GEM_support_sensitivity.tsv','exact_denominator_sensitivity_endpoints.tsv','exact_denominator_baseline_utility.tsv','exact_denominator_CC100_fixed_null_utility.tsv','exact_denominator_CC100_utility_calibration.tsv','equal100_target_cell_summary.tsv','equal100_fixed_baseline_sensitivity.tsv','fixed_list_direction_absolute_summaries.tsv','fixed_direction_agreement.tsv','fixed_list_leave_one_matched_set_out.tsv'))add(file.path(rp,f),'rpe1_validation',description='Source-frozen438-gene RPE1 test; conditional uncertainty and declared or labelled descriptive sensitivity')
for(f in c('source_rank_inputs.tsv','all_source_comparator_rankings.tsv','frozen_background_matches.tsv','null100_source_rankings.tsv.gz','complete_covariate_source_rankings.tsv','complete_covariate_background_matches.tsv','matching_covariate_availability.tsv','matching_estimability_before_RPE1.tsv','complete_covariate_matching_estimability.tsv','matching_balance_before_RPE1.tsv','metadata_eligibility_accounting.tsv','RPE1_phase2_measurement_accounting.tsv','source_UPR_exact_denominator_gene_effects.tsv','rpe1_UPR_exact_denominator_gene_effects.tsv'))add(file.path(ps,f),'rpe1_validation',description='Frozen source inputs, list membership/availability or exact raw-count sensitivity effects')
cc<-fread(file.path(ps,'complete_covariate_null100_rankings.tsv.gz'));keep<-intersect(c('module','gene','rank_cc','Top10_cc','Top20_cc'),names(cc));export(cc[,..keep],'rpe1_validation','complete_covariate_null100_list_membership.tsv.gz','Uniform370-gene sensitivity ranks; source effect/score values are in the full438-gene null100 source table')
top<-fread(file.path(rp,'all438_gene_UPR_response_and_fixed_rank.tsv'))[rank<=20];export(top,'rpe1_validation','fixed_Top20_gene_responses.tsv','Nested fixed Top20/Top10 source and held-out signed UPR effects')
for(f in c('UPR90_control_member_expression.tsv','fixed_Top20_UPR90_member_contrasts.tsv.gz','fixed_Top20_background_gene_effects.tsv','fixed_Top20_leave_one_member_gaps.tsv','leave_one_member_gap_summary.tsv'))add(file.path(ps,'readout_member_sensitivity',f),'rpe1_validation/readout_member_sensitivity',description='Post-outcome descriptive readout-member diagnostic; fixed lists and matches, no reranking')
for(f in c('heldout_metrics.tsv','paired_model_comparisons.tsv','eligible_unit_accounting.tsv'))add(file.path(li,f),'lineage_prediction',description='Measured parent/descendant lineage prediction; primary and stricter support, full-refitting conditional intervals')
for(f in list.files(file.path(cx,'figure_source_data'),pattern='\\.tsv$',full.names=TRUE))add(f,'figure_source_data',description='Exact numerical source for the named final figure panel')
for(f in c('Fig_UPR_external_validation_scatter_source.tsv','Fig_UPR_external_validation_all48_source.tsv','Fig_UPR_external_validation_composition_source.tsv','Fig_independent_candidate_validation_scatter_data.tsv','Fig_independent_candidate_validation_forest_data.tsv'))add(file.path(ex,f),'figure_source_data',description='Exact numerical source for the named final external-validation figure panel')
add(file.path(li,'independent_lineage_figure_source_data.tsv'),'figure_source_data',description='Exact numerical source for final lineage prediction figure')
idx<-rbindlist(index);setorder(idx,file);fwrite(idx,file.path(dst,'table_index.tsv'),sep='\t')
stopifnot(!anyDuplicated(idx$file));cat(nrow(idx),'new tables; total',sum(file.info(file.path(dst,idx$file))$size),'bytes\n')
